package patches.detijd

import app.morphe.patcher.patch.resourcePatch

// Remove only the paper entry from MoreFeedShortcuts. Allocate a dense three-item
// list and retain the original puzzle/video/podcast objects, order and routes.
// The skipped paper-array write becomes two valid LoadConstUndefined r0
// instructions; zero padding would execute Hermes Unreachable opcodes here.
internal val newspaperShortcutEdits = listOf(
    HermesEdit("MoreFeedShortcuts items", 33434, 7133029, 360, 16, 1,
        "0af806414cb218c1abd6441ea3bcd704e8aa2fe31f9c1262df775f82d67efeab",
        "",
        ""),
)

@Suppress("unused")
val hideNewspaperShortcut = resourcePatch(
    name = "Hide newspaper shortcut",
    description = "Removes the Krant card from Meer while preserving Puzzles, Videos and Podcasts.",
) {
    dependsOn(originalInput)
    compatibleWith(detijd)
    execute { patchHermes(get("assets/index.android.bundle"), newspaperShortcutEdits) }
}
